package app.geuncut.tracker;

import java.time.Instant;

import app.geuncut.dto.ItemPrice;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PriceHintTest {
	private static final Instant NOW = Instant.parse("2026-08-14T16:00:00Z");

	@Test
	public void sidePricePicksTheRelevantLeg() {
		ItemPrice price = new ItemPrice(536, 3131L, 3168L, "2026-08-14T15:54:35", "2026-08-14T15:54:40");
		assertEquals(3131L, PriceHint.sidePrice(price, false));
		assertEquals(3168L, PriceHint.sidePrice(price, true));
		assertEquals(0L, PriceHint.sidePrice(null, false));
	}

	@Test
	public void missingLegsAreNotUsable() {
		assertFalse(PriceHint.hasPrices(null));
		assertFalse(PriceHint.hasPrices(new ItemPrice(1, null, 10L, null, null)));
		assertFalse(PriceHint.hasPrices(new ItemPrice(1, 10L, null, null, null)));
		assertFalse(PriceHint.hasPrices(new ItemPrice(1, 0L, 10L, null, null)));
		assertTrue(PriceHint.hasPrices(new ItemPrice(1, 5L, 10L, null, null)));
	}

	@Test
	public void agoReadsNaiveUtcTimestampsAsASingleUnit() {
		assertEquals("now", PriceHint.ago("2026-08-14T15:59:30", NOW));
		assertEquals("3m ago", PriceHint.ago("2026-08-14T15:57:00", NOW));
		assertEquals("2h ago", PriceHint.ago("2026-08-14T14:00:00", NOW));
		assertEquals("2h ago", PriceHint.ago("2026-08-14T13:55:00", NOW));
		assertEquals("2d ago", PriceHint.ago("2026-08-12T15:00:00", NOW));
		assertEquals("?", PriceHint.ago(null, NOW));
	}

	@Test
	public void agoToleratesATrailingZone() {
		assertEquals("3m ago", PriceHint.ago("2026-08-14T15:57:00Z", NOW));
	}
}

package app.geuncut.tracker;

import java.util.List;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class OfferAutofillTest {
	@Test
	public void promptTitlesMapToKinds() {
		assertEquals(OfferAutofill.Prompt.PRICE, OfferAutofill.promptKind("Set a price for each item:"));
		assertEquals(OfferAutofill.Prompt.QUANTITY, OfferAutofill.promptKind("How many do you wish to buy?"));
		assertEquals(OfferAutofill.Prompt.QUANTITY, OfferAutofill.promptKind("How many do you wish to sell?"));
		assertNull(OfferAutofill.promptKind("Enter amount:"));
		assertNull(OfferAutofill.promptKind(null));
	}

	@Test
	public void priceChoicesOfferOurPriceAndBothAdjustments() {
		List<OfferAutofill.Choice> choices = OfferAutofill.choices(2512L, OfferAutofill.Prompt.PRICE, 2);
		assertEquals(3, choices.size());
		assertEquals("-2% 2,462", choices.get(0).getLabel());
		assertEquals(2462, choices.get(0).getValue());
		assertEquals("2,512", choices.get(1).getLabel());
		assertEquals(2512, choices.get(1).getValue());
		assertTrue(choices.get(1).isBase());
		assertEquals("+2% 2,562", choices.get(2).getLabel());
		assertEquals(2562, choices.get(2).getValue());
		assertFalse(choices.get(0).isBase());
		assertFalse(choices.get(2).isBase());
	}

	@Test
	public void zeroPercentKeepsTheSingleOriginalLine() {
		List<OfferAutofill.Choice> choices = OfferAutofill.choices(2512L, OfferAutofill.Prompt.PRICE, 0);
		assertEquals(1, choices.size());
		assertEquals("2,512", choices.get(0).getLabel());
		assertEquals(2512, choices.get(0).getValue());
		assertTrue(choices.get(0).isBase());
	}

	@Test
	public void quantityPromptsAreNeverAdjusted() {
		List<OfferAutofill.Choice> choices = OfferAutofill.choices(10_000L, OfferAutofill.Prompt.QUANTITY, 25);
		assertEquals(1, choices.size());
		assertEquals("10,000", choices.get(0).getLabel());
		assertEquals(10_000, choices.get(0).getValue());
	}

	@Test
	public void adjustedPricesRoundAndNeverFallBelowOne() {
		List<OfferAutofill.Choice> rounded = OfferAutofill.choices(1005L, OfferAutofill.Prompt.PRICE, 3);
		assertEquals(975, rounded.get(0).getValue());
		assertEquals(1035, rounded.get(2).getValue());
		List<OfferAutofill.Choice> tiny = OfferAutofill.choices(1L, OfferAutofill.Prompt.PRICE, 50);
		assertEquals(1, tiny.get(0).getValue());
		assertEquals(2, tiny.get(2).getValue());
	}

	@Test
	public void compactLabelsStayShortAtEveryPrice() {
		long[] prices = { 2_512L, 250_000L, 3_210_118L, 116_198_605L, 2_147_483_647L };
		for (long price : prices) {
			for (OfferAutofill.Choice choice : OfferAutofill.choices(price, OfferAutofill.Prompt.PRICE, 2, true)) {
				assertTrue(choice.getLabel() + " is too wide to render at price " + price,
						choice.getLabel().length() <= 12);
			}
		}
	}

	@Test
	public void compactFormattingKeepsSmallNumbersExact() {
		assertEquals("2,512", OfferAutofill.choices(2_512L, OfferAutofill.Prompt.PRICE, 0, true).get(0).getLabel());
		assertEquals("99,999", OfferAutofill.choices(99_999L, OfferAutofill.Prompt.PRICE, 0, true).get(0).getLabel());
	}

	@Test
	public void compactFormattingAbbreviatesTheBigOnes() {
		assertEquals("3.21M", OfferAutofill.choices(3_210_118L, OfferAutofill.Prompt.PRICE, 0, true).get(0).getLabel());
		assertEquals("2.15B", OfferAutofill.choices(2_147_483_647L, OfferAutofill.Prompt.PRICE, 0, true).get(0).getLabel());
		assertEquals("250K", OfferAutofill.choices(250_000L, OfferAutofill.Prompt.PRICE, 0, true).get(0).getLabel());
	}

	@Test
	public void compactChoicesStillCarryTheExactGp() {
		List<OfferAutofill.Choice> choices =
				OfferAutofill.choices(3_210_118L, OfferAutofill.Prompt.PRICE, 1, true);
		assertEquals(3_178_017L, choices.get(0).getValue());
		assertEquals(3_210_118L, choices.get(1).getValue());
		assertEquals(3_242_219L, choices.get(2).getValue());
	}

	@Test
	public void missingValuesProduceNoChoices() {
		assertTrue(OfferAutofill.choices(null, OfferAutofill.Prompt.PRICE, 2).isEmpty());
		assertTrue(OfferAutofill.choices(0L, OfferAutofill.Prompt.PRICE, 2).isEmpty());
	}
}

package app.geuncut.tracker;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import app.geuncut.model.OfferDelta;
import app.geuncut.model.OfferSnapshot;
import app.geuncut.tracker.impl.InMemorySnapshotStore;
import app.geuncut.tracker.impl.OfferTrackerImpl;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Before;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.BOUGHT;
import static net.runelite.api.GrandExchangeOfferState.BUYING;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_BUY;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_SELL;
import static net.runelite.api.GrandExchangeOfferState.EMPTY;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class OfferTrackerTest {
	private static final Instant T0 = Instant.parse("2026-07-05T12:00:00Z");
	private static final int TBOW = 20997;

	private OfferTracker tracker;

	@Before
	public void setUp() {
		tracker = new OfferTrackerImpl();
	}

	private static Optional<OfferDelta> change(OfferTracker target, int slot, int itemId,
			GrandExchangeOfferState state, int quantitySold, int spent, int totalQuantity, int price) {
		List<OfferDelta> fills = new ArrayList<>();
		target.onOfferChanged(slot, itemId, state, quantitySold, spent, totalQuantity, price, T0, fills::add);
		return fills.isEmpty() ? Optional.empty() : Optional.of(fills.get(0));
	}

	private Optional<OfferDelta> change(int slot, int itemId, GrandExchangeOfferState state,
			int quantitySold, int spent, int totalQuantity, int price) {
		return change(tracker, slot, itemId, state, quantitySold, spent, totalQuantity, price);
	}

	@Test
	public void freshBuyEmitsDeltaPerFill() {
		assertFalse(change(0, TBOW, BUYING, 0, 0, 8, 1_000_000).isPresent());

		Optional<OfferDelta> first = change(0, TBOW, BUYING, 3, 3_000_000, 8, 1_000_000);
		assertTrue(first.isPresent());
		assertEquals(OfferDelta.Side.BUY, first.get().getSide());
		assertEquals(3, first.get().getQuantity());
		assertEquals(1_000_000, first.get().getPriceEach());
		assertEquals(3, first.get().getCumulativeQuantitySold());

		Optional<OfferDelta> second = change(0, TBOW, BOUGHT, 8, 8_100_000, 8, 1_000_000);
		assertTrue(second.isPresent());
		assertEquals(5, second.get().getQuantity());
		assertEquals(1_020_000, second.get().getPriceEach());
		assertEquals(8, second.get().getCumulativeQuantitySold());
	}

	@Test
	public void oneOfferKeepsOneIdAcrossItsFills() {
		change(0, TBOW, BUYING, 0, 0, 8, 1_000_000);
		Optional<OfferDelta> first = change(0, TBOW, BUYING, 3, 3_000_000, 8, 1_000_000);
		Optional<OfferDelta> second = change(0, TBOW, BOUGHT, 8, 8_000_000, 8, 1_000_000);

		assertNotNull(first.get().getOfferId());
		assertEquals(first.get().getOfferId(), second.get().getOfferId());
	}

	@Test
	public void aNewOfferInTheSameSlotGetsANewId() {
		change(0, TBOW, BUYING, 0, 0, 8, 1_000_000);
		Optional<OfferDelta> first = change(0, TBOW, BOUGHT, 8, 8_000_000, 8, 1_000_000);
		change(0, TBOW, EMPTY, 0, 0, 0, 0);

		change(0, TBOW, BUYING, 0, 0, 8, 1_000_000);
		Optional<OfferDelta> second = change(0, TBOW, BUYING, 8, 8_000_000, 8, 1_000_000);

		assertTrue(second.isPresent());
		assertFalse(first.get().getOfferId().equals(second.get().getOfferId()));
	}

	@Test
	public void aDifferentItemInTheSameSlotGetsANewId() {
		change(0, TBOW, BUYING, 0, 0, 8, 1_000_000);
		Optional<OfferDelta> first = change(0, TBOW, BUYING, 2, 2_000_000, 8, 1_000_000);
		Optional<OfferDelta> other = change(0, 4151, BUYING, 2, 3_000_000, 8, 1_500_000);

		assertTrue(other.isPresent());
		assertFalse(first.get().getOfferId().equals(other.get().getOfferId()));
	}

	@Test
	public void aQuantityThatGoesBackwardsStartsANewOffer() {
		change(2, TBOW, BUYING, 0, 0, 8, 1_000_000);
		Optional<OfferDelta> first = change(2, TBOW, BUYING, 5, 5_000_000, 8, 1_000_000);
		change(2, TBOW, BUYING, 1, 1_000_000, 8, 1_000_000);
		Optional<OfferDelta> after = change(2, TBOW, BUYING, 4, 4_000_000, 8, 1_000_000);

		assertTrue(after.isPresent());
		assertFalse(first.get().getOfferId().equals(after.get().getOfferId()));
	}

	@Test
	public void theOfferIdIsPersistedWithTheBaseline() {
		InMemorySnapshotStore store = new InMemorySnapshotStore();
		OfferTracker durable = new OfferTrackerImpl(store);
		durable.loadFor("acct-1");
		change(durable, 3, TBOW, SELLING, 0, 0, 6_250, 20_400);
		Optional<OfferDelta> live = change(durable, 3, TBOW, SELLING, 2_175, 44_370_000, 6_250, 20_400);

		OfferSnapshot stored = store.load("acct-1").get(3);
		assertEquals(live.get().getOfferId(), stored.getOfferId());

		durable.reset();
		durable.loadFor("acct-1");
		Optional<OfferDelta> awayFill = change(durable, 3, TBOW, SOLD, 6_250, 127_500_000, 6_250, 20_400);
		assertEquals("the same offer must keep its id across a relog",
				live.get().getOfferId(), awayFill.get().getOfferId());
		assertEquals(6_250, awayFill.get().getCumulativeQuantitySold());
	}

	@Test
	public void aBaselineFromBeforeOfferIdsIsGivenOneOnFirstTouch() {
		InMemorySnapshotStore store = new InMemorySnapshotStore();
		Map<Integer, OfferSnapshot> legacy = new HashMap<>();
		legacy.put(1, new OfferSnapshot(TBOW, 100, 100_000_000, SELLING, 500, 1_000_000, null));
		store.save("acct-1", legacy);

		OfferTracker durable = new OfferTrackerImpl(store);
		durable.loadFor("acct-1");
		Optional<OfferDelta> fill = change(durable, 1, TBOW, SELLING, 150, 150_000_000, 500, 1_000_000);

		assertTrue(fill.isPresent());
		assertNotNull(fill.get().getOfferId());
		assertEquals(fill.get().getOfferId(), store.load("acct-1").get(1).getOfferId());
	}

	@Test
	public void theFillIsHandedOverBeforeTheBaselineIsPersisted() {
		List<String> order = new ArrayList<>();
		SnapshotStore recording = new SnapshotStore() {
			@Override
			public Map<Integer, OfferSnapshot> load(String accountHash) {
				return new HashMap<>();
			}

			@Override
			public void save(String accountHash, Map<Integer, OfferSnapshot> slots) {
				order.add("persist");
			}
		};
		OfferTracker durable = new OfferTrackerImpl(recording);
		durable.loadFor("acct-1");
		change(durable, 0, TBOW, BUYING, 0, 0, 8, 1_000_000);
		order.clear();

		durable.onOfferChanged(0, TBOW, BUYING, 3, 3_000_000, 8, 1_000_000, T0, delta -> order.add("append"));

		assertEquals(Arrays.asList("append", "persist"), order);
	}

	@Test
	public void loginReplayOfPartialOfferIsBaselineNotFill() {
		Optional<OfferDelta> replay = change(2, TBOW, BUYING, 5, 5_000_000, 8, 1_000_000);
		assertFalse(replay.isPresent());

		Optional<OfferDelta> next = change(2, TBOW, BUYING, 6, 6_000_000, 8, 1_000_000);
		assertTrue(next.isPresent());
		assertEquals(1, next.get().getQuantity());
	}

	@Test
	public void relogWithSameOfferDoesNotDoubleCount() {
		change(1, TBOW, BUYING, 0, 0, 8, 1_000_000);
		change(1, TBOW, BUYING, 4, 4_000_000, 8, 1_000_000);
		tracker.reset();

		Optional<OfferDelta> replay = change(1, TBOW, BUYING, 4, 4_000_000, 8, 1_000_000);
		assertFalse(replay.isPresent());
	}

	@Test
	public void cancelledBuyEmitsOnlyTheFilledPortion() {
		change(0, TBOW, BUYING, 0, 0, 8, 1_000_000);
		change(0, TBOW, BUYING, 2, 2_000_000, 8, 1_000_000);

		Optional<OfferDelta> onCancel = change(0, TBOW, CANCELLED_BUY, 2, 2_000_000, 8, 1_000_000);
		assertFalse(onCancel.isPresent());
	}

	@Test
	public void sellSideEmitsSellDeltas() {
		change(3, TBOW, SELLING, 0, 0, 8, 1_500_000);
		Optional<OfferDelta> sold = change(3, TBOW, SOLD, 8, 12_000_000, 8, 1_500_000);
		assertTrue(sold.isPresent());
		assertEquals(OfferDelta.Side.SELL, sold.get().getSide());
		assertEquals(8, sold.get().getQuantity());
		assertEquals(1_500_000, sold.get().getPriceEach());
	}

	@Test
	public void emptySlotResetsAndNextOfferStartsClean() {
		change(0, TBOW, BUYING, 0, 0, 8, 1_000_000);
		change(0, TBOW, BOUGHT, 8, 8_000_000, 8, 1_000_000);
		change(0, TBOW, EMPTY, 0, 0, 0, 0);

		assertFalse(change(0, TBOW, BUYING, 0, 0, 8, 1_000_000).isPresent());
		Optional<OfferDelta> fill = change(0, TBOW, BUYING, 1, 1_000_000, 8, 1_000_000);
		assertTrue(fill.isPresent());
		assertEquals(1, fill.get().getQuantity());
	}

	@Test
	public void reusedSlotWhoseFirstEventAlreadyFilledIsCounted() {
		change(0, TBOW, BUYING, 0, 0, 8, 1_000_000);
		change(0, TBOW, BOUGHT, 8, 8_000_000, 8, 1_000_000);
		change(0, TBOW, EMPTY, 0, 0, 0, 0);

		Optional<OfferDelta> fill = change(0, 4151, BUYING, 5, 5_000_000, 8, 1_000_000);
		assertTrue(fill.isPresent());
		assertEquals(5, fill.get().getQuantity());
		assertEquals(1_000_000, fill.get().getPriceEach());
	}

	@Test
	public void largeSpendComputesAnExactUnitPrice() {
		change(1, TBOW, BUYING, 0, 0, 1, 1_500_000_001);
		Optional<OfferDelta> fill = change(1, TBOW, BOUGHT, 1, 1_500_000_001, 1, 1_500_000_001);
		assertTrue(fill.isPresent());
		assertEquals(1_500_000_001, fill.get().getPriceEach());
	}

	@Test
	public void slotReuseWithDifferentItemStartsClean() {
		change(0, TBOW, BUYING, 0, 0, 8, 1_000_000);
		change(0, TBOW, BOUGHT, 8, 8_000_000, 8, 1_000_000);

		Optional<OfferDelta> otherItem = change(0, 4151, BUYING, 2, 3_000_000, 8, 1_500_000);
		assertTrue(otherItem.isPresent());
		assertEquals(2, otherItem.get().getQuantity());
		assertEquals(1_500_000, otherItem.get().getPriceEach());
	}


	@Test
	public void completionRacingCollectionBooksTheResidualAtTheOfferPrice() {
		change(2, TBOW, SELLING, 0, 0, 4_000, 21_000);
		Optional<OfferDelta> catchUp = change(2, TBOW, SELLING, 3_430, 72_030_000, 4_000, 21_000);
		assertTrue(catchUp.isPresent());
		assertEquals(3_430, catchUp.get().getQuantity());

		Optional<OfferDelta> residual = change(2, TBOW, EMPTY, 0, 0, 0, 0);
		assertTrue(residual.isPresent());
		assertEquals(OfferDelta.Side.SELL, residual.get().getSide());
		assertEquals(570, residual.get().getQuantity());
		assertEquals(21_000, residual.get().getPriceEach());
		assertEquals(catchUp.get().getOfferId(), residual.get().getOfferId());
		assertEquals(4_000, residual.get().getCumulativeQuantitySold());
	}

	@Test
	public void buySideCompletionRaceAlsoBooksTheResidual() {
		change(1, TBOW, BUYING, 0, 0, 10, 500);
		change(1, TBOW, BUYING, 4, 2_000, 10, 500);

		Optional<OfferDelta> residual = change(1, TBOW, EMPTY, 0, 0, 0, 0);
		assertTrue(residual.isPresent());
		assertEquals(OfferDelta.Side.BUY, residual.get().getSide());
		assertEquals(6, residual.get().getQuantity());
		assertEquals(500, residual.get().getPriceEach());
	}

	@Test
	public void abortedOfferClearsWithNoResidual() {
		change(0, TBOW, SELLING, 0, 0, 4_000, 21_000);
		change(0, TBOW, SELLING, 3_430, 72_030_000, 4_000, 21_000);
		change(0, TBOW, CANCELLED_SELL, 3_430, 72_030_000, 4_000, 21_000);

		assertFalse(change(0, TBOW, EMPTY, 0, 0, 0, 0).isPresent());
	}

	@Test
	public void completedOfferCollectedNormallyHasNoResidual() {
		change(0, TBOW, BUYING, 0, 0, 8, 1_000_000);
		change(0, TBOW, BOUGHT, 8, 8_000_000, 8, 1_000_000);

		assertFalse(change(0, TBOW, EMPTY, 0, 0, 0, 0).isPresent());
	}

	@Test
	public void slotCollectedWhileAwayHasNoSnapshotAndNoResidual() {
		assertFalse(change(3, TBOW, EMPTY, 0, 0, 0, 0).isPresent());
	}

	@Test
	public void reloadedBaselineAcrossRelogEmitsTheAwayFills() {
		InMemorySnapshotStore store = new InMemorySnapshotStore();
		OfferTracker durable = new OfferTrackerImpl(store);
		durable.loadFor("acct-1");

		assertFalse(change(durable, 3, TBOW, SELLING, 0, 0, 6_250, 20_400).isPresent());
		Optional<OfferDelta> live = change(durable, 3, TBOW, SELLING, 2_175, 44_370_000, 6_250, 20_400);
		assertTrue(live.isPresent());
		assertEquals(2_175, live.get().getQuantity());

		durable.reset();
		durable.loadFor("acct-1");

		Optional<OfferDelta> awayFill = change(durable, 3, TBOW, SOLD, 6_250, 127_500_000, 6_250, 20_400);
		assertTrue(awayFill.isPresent());
		assertEquals(OfferDelta.Side.SELL, awayFill.get().getSide());
		assertEquals(4_075, awayFill.get().getQuantity());
	}

	@Test
	public void reloadedBaselineDoesNotDoubleCountAnUnchangedOffer() {
		InMemorySnapshotStore store = new InMemorySnapshotStore();
		OfferTracker durable = new OfferTrackerImpl(store);
		durable.loadFor("acct-1");

		change(durable, 3, TBOW, SELLING, 0, 0, 6_250, 20_400);
		change(durable, 3, TBOW, SELLING, 2_175, 44_370_000, 6_250, 20_400);

		durable.reset();
		durable.loadFor("acct-1");

		assertFalse(change(durable, 3, TBOW, SELLING, 2_175, 44_370_000, 6_250, 20_400).isPresent());
	}

	@Test
	public void reloadIsScopedToTheLoggedInAccount() {
		InMemorySnapshotStore store = new InMemorySnapshotStore();
		OfferTracker durable = new OfferTrackerImpl(store);
		durable.loadFor("main");
		change(durable, 3, TBOW, SELLING, 0, 0, 6_250, 20_400);
		change(durable, 3, TBOW, SELLING, 2_175, 44_370_000, 6_250, 20_400);

		durable.reset();
		durable.loadFor("alt");

		assertFalse(change(durable, 3, 4151, SELLING, 900, 900_000, 1_000, 1_000).isPresent());
		Optional<OfferDelta> altFill = change(durable, 3, 4151, SELLING, 950, 950_000, 1_000, 1_000);
		assertTrue(altFill.isPresent());
		assertEquals(50, altFill.get().getQuantity());
	}
}

package app.geuncut.tracker;

import java.time.Duration;
import java.time.Instant;

import app.geuncut.tracker.impl.BuyLimitTrackerImpl;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class BuyLimitTrackerTest {
	private static final Instant T0 = Instant.parse("2026-07-05T12:00:00Z");
	private static final int TBOW = 20997;

	private BuyLimitTracker tracker;

	@Before
	public void setUp() {
		tracker = new BuyLimitTrackerImpl();
	}

	@Test
	public void sumsPurchasesInsideTheWindow() {
		tracker.recordBuy(TBOW, 3, T0);
		tracker.recordBuy(TBOW, 2, T0.plus(Duration.ofMinutes(30)));
		assertEquals(5, tracker.boughtInWindow(TBOW, T0.plus(Duration.ofHours(1))));
	}

	@Test
	public void purchasesRollOffAfterFourHours() {
		tracker.recordBuy(TBOW, 3, T0);
		tracker.recordBuy(TBOW, 2, T0.plus(Duration.ofHours(2)));

		Instant later = T0.plus(Duration.ofHours(4)).plusSeconds(1);
		assertEquals(2, tracker.boughtInWindow(TBOW, later));
	}

	@Test
	public void nextResetIsOldestPurchasePlusWindow() {
		tracker.recordBuy(TBOW, 3, T0);
		tracker.recordBuy(TBOW, 2, T0.plus(Duration.ofHours(1)));

		assertEquals(T0.plus(Duration.ofHours(4)),
				tracker.nextReset(TBOW, T0.plus(Duration.ofHours(2))).orElseThrow(AssertionError::new));
	}

	@Test
	public void noPurchasesMeansNoReset() {
		assertFalse(tracker.nextReset(TBOW, T0).isPresent());
		assertEquals(0, tracker.boughtInWindow(TBOW, T0));
	}

	@Test
	public void itemsAreIndependent() {
		tracker.recordBuy(TBOW, 8, T0);
		assertEquals(0, tracker.boughtInWindow(4151, T0.plusSeconds(60)));
		assertTrue(tracker.nextReset(TBOW, T0.plusSeconds(60)).isPresent());
	}
}

package app.geuncut.tracker;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardOpenOption;
import java.util.List;

import app.geuncut.dto.GeTradeEvent;
import app.geuncut.tracker.impl.FileFillLog;
import com.google.gson.Gson;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class FileFillLogTest {
	private File dir;
	private Gson gson;

	@Before
	public void setUp() throws Exception {
		dir = Files.createTempDirectory("filllog").toFile();
		gson = new Gson();
	}

	@After
	public void tearDown() {
		for (File f : dir.listFiles() != null ? dir.listFiles() : new File[0]) {
			f.delete();
		}
		dir.delete();
	}

	private static GeTradeEvent event(String key, int qty) {
		return GeTradeEvent.builder()
				.accountHash("acct-1").idempotencyKey(key).clientEventId(key)
				.itemId(20997).side("buy").quantity(qty).priceEach(1000).slot(0)
				.occurredAt("2026-07-05T12:00:00Z").build();
	}

	private File logFile(String accountHash) {
		return new File(dir, "fills-" + accountHash + ".jsonl");
	}

	private int lineCount(String accountHash) throws Exception {
		File file = logFile(accountHash);
		if (!file.isFile()) {
			return 0;
		}
		return Files.readAllLines(file.toPath(), StandardCharsets.UTF_8).size();
	}

	@Test
	public void appendThenReadRoundTripsTheFill() {
		FileFillLog log = new FileFillLog(gson, dir);
		log.append("acct-1", event("k1", 7));

		FillBatch batch = log.read("acct-1", 0, 50);
		assertEquals(1, batch.getEntries().size());
		assertEquals("k1", batch.getEntries().get(0).getIdempotencyKey());
		assertEquals(7, batch.getEntries().get(0).getQuantity());
		assertEquals("buy", batch.getEntries().get(0).getSide());
		assertEquals(logFile("acct-1").length(), batch.getNextOffset());
	}

	@Test
	public void appendStampsTheOrdinalOfEveryEntry() {
		FileFillLog log = new FileFillLog(gson, dir);
		log.append("acct-1", event("k1", 1));
		log.append("acct-1", event("k2", 2));
		log.append("acct-1", event("k3", 3));

		List<GeTradeEvent> entries = log.read("acct-1", 0, 50).getEntries();
		assertEquals(Long.valueOf(0), entries.get(0).getSeq());
		assertEquals(Long.valueOf(1), entries.get(1).getSeq());
		assertEquals(Long.valueOf(2), entries.get(2).getSeq());
	}

	@Test
	public void theOrdinalKeepsCountingAfterAReopen() {
		new FileFillLog(gson, dir).append("acct-1", event("k1", 1));
		FileFillLog reopened = new FileFillLog(gson, dir);
		reopened.append("acct-1", event("k2", 2));

		List<GeTradeEvent> entries = reopened.read("acct-1", 0, 50).getEntries();
		assertEquals(Long.valueOf(0), entries.get(0).getSeq());
		assertEquals(Long.valueOf(1), entries.get(1).getSeq());
	}

	@Test
	public void entriesSurviveReopening() {
		new FileFillLog(gson, dir).append("acct-1", event("k1", 3));
		List<GeTradeEvent> entries = new FileFillLog(gson, dir).read("acct-1", 0, 50).getEntries();
		assertEquals(1, entries.size());
		assertEquals(3, entries.get(0).getQuantity());
	}

	@Test
	public void markingDeliveredNeverRemovesALine() throws Exception {
		FileFillLog log = new FileFillLog(gson, dir);
		log.append("acct-1", event("k1", 1));
		log.append("acct-1", event("k2", 2));
		long everything = log.read("acct-1", 0, 50).getNextOffset();

		log.markDelivered("acct-1", everything);

		assertEquals(2, lineCount("acct-1"));
		assertTrue(logFile("acct-1").isFile());
		assertEquals(2, log.read("acct-1", 0, 50).getEntries().size());
		assertTrue(log.read("acct-1", everything, 50).getEntries().isEmpty());
	}

	@Test
	public void theDeliveredCursorSurvivesReopening() {
		FileFillLog log = new FileFillLog(gson, dir);
		log.append("acct-1", event("k1", 1));
		log.append("acct-1", event("k2", 2));
		long afterFirst = log.read("acct-1", 0, 1).getNextOffset();
		log.markDelivered("acct-1", afterFirst);

		FileFillLog reopened = new FileFillLog(gson, dir);
		assertEquals(afterFirst, reopened.deliveredOffset("acct-1"));
		List<GeTradeEvent> rest = reopened.read("acct-1", reopened.deliveredOffset("acct-1"), 50).getEntries();
		assertEquals(1, rest.size());
		assertEquals("k2", rest.get(0).getIdempotencyKey());
	}

	@Test
	public void aMissingCursorStartsAtZero() {
		FileFillLog log = new FileFillLog(gson, dir);
		log.append("acct-1", event("k1", 1));
		assertEquals(0, log.deliveredOffset("acct-1"));
	}

	@Test
	public void aCorruptCursorStartsAtZero() throws Exception {
		FileFillLog log = new FileFillLog(gson, dir);
		log.append("acct-1", event("k1", 1));
		Files.write(new File(dir, "fills-acct-1.sent").toPath(), "not-a-number".getBytes(StandardCharsets.UTF_8));

		assertEquals(0, log.deliveredOffset("acct-1"));
		assertEquals(1, log.read("acct-1", log.deliveredOffset("acct-1"), 50).getEntries().size());
	}

	@Test
	public void aCursorPastTheEndOfTheLogClampsToTheLog() throws Exception {
		FileFillLog log = new FileFillLog(gson, dir);
		log.append("acct-1", event("k1", 1));
		Files.write(new File(dir, "fills-acct-1.sent").toPath(), "999999".getBytes(StandardCharsets.UTF_8));

		assertEquals(logFile("acct-1").length(), log.deliveredOffset("acct-1"));
	}

	@Test
	public void theCursorNeverMovesBackwards() {
		FileFillLog log = new FileFillLog(gson, dir);
		log.append("acct-1", event("k1", 1));
		log.append("acct-1", event("k2", 2));
		long everything = log.read("acct-1", 0, 50).getNextOffset();
		log.markDelivered("acct-1", everything);

		log.markDelivered("acct-1", 0);

		assertEquals(everything, log.deliveredOffset("acct-1"));
	}

	@Test
	public void readingFromAnOffsetReturnsOnlyWhatIsNew() {
		FileFillLog log = new FileFillLog(gson, dir);
		log.append("acct-1", event("k1", 1));
		log.append("acct-1", event("k2", 2));
		FillBatch first = log.read("acct-1", 0, 1);
		assertEquals("k1", first.getEntries().get(0).getIdempotencyKey());

		FillBatch second = log.read("acct-1", first.getNextOffset(), 1);
		assertEquals(1, second.getEntries().size());
		assertEquals("k2", second.getEntries().get(0).getIdempotencyKey());
		assertTrue(log.read("acct-1", second.getNextOffset(), 50).getEntries().isEmpty());
	}

	@Test
	public void aTornLastWriteCannotBleedIntoTheNextEntry() throws Exception {
		FileFillLog log = new FileFillLog(gson, dir);
		log.append("acct-1", event("k1", 1));
		Files.write(logFile("acct-1").toPath(), "{\"idempotency_key\":\"k2\",\"quan".getBytes(StandardCharsets.UTF_8),
				StandardOpenOption.APPEND);

		FileFillLog reopened = new FileFillLog(gson, dir);
		reopened.append("acct-1", event("k3", 3));

		List<GeTradeEvent> entries = reopened.read("acct-1", 0, 50).getEntries();
		assertEquals(2, entries.size());
		assertEquals("k1", entries.get(0).getIdempotencyKey());
		assertEquals("k3", entries.get(1).getIdempotencyKey());
		assertEquals(3, entries.get(1).getQuantity());
	}

	@Test
	public void anUnparseableLineIsSkippedWithoutStallingTheCursor() throws Exception {
		FileFillLog log = new FileFillLog(gson, dir);
		log.append("acct-1", event("k1", 1));
		Files.write(logFile("acct-1").toPath(), "{ not json\n".getBytes(StandardCharsets.UTF_8),
				StandardOpenOption.APPEND);
		log.append("acct-1", event("k3", 3));

		FillBatch batch = new FileFillLog(gson, dir).read("acct-1", 0, 50);
		assertEquals(2, batch.getEntries().size());
		assertEquals("k3", batch.getEntries().get(1).getIdempotencyKey());
		assertEquals(logFile("acct-1").length(), batch.getNextOffset());
	}

	@Test
	public void accountsAreIsolated() {
		FileFillLog log = new FileFillLog(gson, dir);
		log.append("acct-1", event("a", 1));
		log.append("acct-2", event("b", 2));

		assertEquals(1, log.read("acct-1", 0, 50).getEntries().size());
		assertEquals(1, log.read("acct-2", 0, 50).getEntries().size());
		assertEquals("a", log.read("acct-1", 0, 50).getEntries().get(0).getIdempotencyKey());

		log.markDelivered("acct-1", log.read("acct-1", 0, 50).getNextOffset());
		assertTrue(log.read("acct-1", log.deliveredOffset("acct-1"), 50).getEntries().isEmpty());
		assertEquals(0, log.deliveredOffset("acct-2"));
		assertEquals(1, log.read("acct-2", 0, 50).getEntries().size());
	}

	@Test
	public void unknownAccountAndNullsAreSafe() {
		FileFillLog log = new FileFillLog(gson, dir);
		assertTrue(log.read("nobody", 0, 50).getEntries().isEmpty());
		assertEquals(0, log.deliveredOffset("nobody"));
		log.append(null, event("k", 1));
		log.append("acct-1", null);
		log.markDelivered(null, 10);
		assertTrue(log.read("acct-1", 0, 50).getEntries().isEmpty());
		assertFalse(logFile("acct-1").isFile());
	}
}

package app.geuncut.tracker;

import java.util.List;

import app.geuncut.dto.GeHistoryRow;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GeHistoryParserTest {
	private static Widget text(String value) {
		Widget widget = mock(Widget.class);
		when(widget.getText()).thenReturn(value);
		when(widget.getItemId()).thenReturn(-1);
		return widget;
	}

	private static Widget item(int itemId, int quantity) {
		Widget widget = mock(Widget.class);
		when(widget.getText()).thenReturn("");
		when(widget.getItemId()).thenReturn(itemId);
		when(widget.getItemQuantity()).thenReturn(quantity);
		return widget;
	}

	private static Widget container(Widget... children) {
		Widget widget = mock(Widget.class);
		when(widget.getDynamicChildren()).thenReturn(children);
		return widget;
	}

	@Test
	public void parsesSoldAndBoughtRowsWithTaxBreakdown() {
		Widget container = container(
				text("<col=ff981f>Sold:</col>"),
				text("Superior dragon bones<br>x 5,000"),
				item(22124, 5000),
				text("105,350,000 coins (107,500,000 - 2,150,000) = 21,070 each"),
				text("Bought:"),
				text("Superior dragon bones<br>x 2,908"),
				item(22124, 2908),
				text("60,643,432 coins = 20,854 each"));

		List<GeHistoryRow> rows = GeHistoryParser.parse(container);

		assertEquals(2, rows.size());
		assertEquals("sell", rows.get(0).getSide());
		assertEquals(22124, rows.get(0).getItemId());
		assertEquals(5000, rows.get(0).getQuantity());
		assertEquals(21070, rows.get(0).getPriceEach());
		assertEquals("buy", rows.get(1).getSide());
		assertEquals(2908, rows.get(1).getQuantity());
		assertEquals(20854, rows.get(1).getPriceEach());
	}

	@Test
	public void singleUnitRowFallsBackToCoinsTotal() {
		Widget container = container(
				text("Bought:"),
				text("Twisted bow<br>x 1"),
				item(20997, 1),
				text("1,400,000,000 coins"));

		List<GeHistoryRow> rows = GeHistoryParser.parse(container);

		assertEquals(1, rows.size());
		assertEquals("buy", rows.get(0).getSide());
		assertEquals(1, rows.get(0).getQuantity());
		assertEquals(1_400_000_000, rows.get(0).getPriceEach());
	}

	@Test
	public void headerWithoutItemOrPriceIsSkipped() {
		Widget container = container(
				text("Sold:"),
				text("Superior dragon bones<br>x 5,000"),
				text("Bought:"),
				text("Shark<br>x 100"),
				item(385, 100),
				text("80,000 coins = 800 each"));

		List<GeHistoryRow> rows = GeHistoryParser.parse(container);

		assertEquals(1, rows.size());
		assertEquals("buy", rows.get(0).getSide());
		assertEquals(385, rows.get(0).getItemId());
	}

	@Test
	public void colorTagDigitsNeverPolluteNumbers() {
		Widget container = container(
				text("Sold:"),
				text("Cannonball<br>x 2,000"),
				item(2, 2000),
				text("<col=ffb83f>400,000 coins (408,163 - 8,163) = 200 each</col>"));

		List<GeHistoryRow> rows = GeHistoryParser.parse(container);

		assertEquals(1, rows.size());
		assertEquals(200, rows.get(0).getPriceEach());
	}

	@Test
	public void nullOrEmptyContainerParsesToNothing() {
		assertTrue(GeHistoryParser.parse(null).isEmpty());
		assertTrue(GeHistoryParser.parse(container()).isEmpty());
	}

	@Test
	public void rowWithUnparseablePriceIsSkippedNotGuessed() {
		Widget container = container(
				text("Sold:"),
				item(22124, 100),
				text("some coins = garbage each"),
				text("Bought:"),
				item(385, 50),
				text("40,000 coins = 800 each"));

		List<GeHistoryRow> rows = GeHistoryParser.parse(container);

		assertEquals(1, rows.size());
		assertEquals(385, rows.get(0).getItemId());
	}

	@Test
	public void nextRowNeverBleedsIntoAPartialOne() {
		Widget container = container(
				text("Sold:"),
				item(22124, 100),
				text("Bought:"),
				item(385, 50),
				text("40,000 coins = 800 each"));

		List<GeHistoryRow> rows = GeHistoryParser.parse(container);

		assertEquals(1, rows.size());
		assertEquals("buy", rows.get(0).getSide());
		assertEquals(385, rows.get(0).getItemId());
		assertEquals(800, rows.get(0).getPriceEach());
	}

	@Test
	public void fillerChildrenBeyondScanLimitDropTheRow() {
		Widget[] children = new Widget[12];
		children[0] = text("Sold:");
		for (int index = 1; index < 10; index++) {
			children[index] = text("");
		}
		children[10] = item(22124, 100);
		children[11] = text("2,000,000 coins = 20,000 each");

		assertTrue(GeHistoryParser.parse(container(children)).isEmpty());
	}

	@Test
	public void zeroQuantityItemWidgetDefaultsToOne() {
		Widget container = container(
				text("Bought:"),
				item(20997, 0),
				text("1,400,000,000 coins"));

		List<GeHistoryRow> rows = GeHistoryParser.parse(container);

		assertEquals(1, rows.size());
		assertEquals(1, rows.get(0).getQuantity());
	}

	@Test
	public void fullHistoryWindowOfMixedRowsParsesEveryEntry() {
		Widget[] children = new Widget[8 * 4];
		for (int entry = 0; entry < 8; entry++) {
			int base = entry * 4;
			boolean sell = entry % 2 == 0;
			children[base] = text(sell ? "Sold:" : "Bought:");
			children[base + 1] = text("Item " + entry + "<br>x 10");
			children[base + 2] = item(1_000 + entry, 10);
			children[base + 3] = text(sell
					? "10,000 coins (10,205 - 205) = 1,000 each"
					: "10,000 coins = 1,000 each");
		}

		List<GeHistoryRow> rows = GeHistoryParser.parse(container(children));

		assertEquals(8, rows.size());
		for (int entry = 0; entry < 8; entry++) {
			assertEquals(1_000 + entry, rows.get(entry).getItemId());
			assertEquals(entry % 2 == 0 ? "sell" : "buy", rows.get(entry).getSide());
			assertEquals(1_000, rows.get(entry).getPriceEach());
		}
	}
}

