	private static void collectAllLabelTexts(Component component, java.util.List<String> out) {
		if (component instanceof JLabel) {
			out.add(((JLabel) component).getText());
		}
		if (component instanceof Container) {
			for (Component child : ((Container) component).getComponents()) {
				collectAllLabelTexts(child, out);
			}
		}
	}

	private static AbstractButton findButton(Component component, String text) {
		if (component instanceof AbstractButton && text.equals(((AbstractButton) component).getText())) {
			return (AbstractButton) component;
		}
		if (component instanceof Container) {
			for (Component child : ((Container) component).getComponents()) {
				AbstractButton found = findButton(child, text);
				if (found != null) {
					return found;
				}
			}
		}
		return null;
	}

	private static JLabel findLabel(Component component, String text) {
		if (component instanceof JLabel && text.equals(((JLabel) component).getText())) {
			return (JLabel) component;
		}
		if (component instanceof Container) {
			for (Component child : ((Container) component).getComponents()) {
				JLabel found = findLabel(child, text);
				if (found != null) {
					return found;
				}
			}
		}
		return null;
	}

	private static JLabel helpChipFor(Component component, String word) {
		if (component instanceof JLabel) {
			JLabel label = (JLabel) component;
			String tip = label.getToolTipText();
			if ("?".equals(label.getText()) && tip != null && tip.contains(word)) {
				return label;
			}
		}
		if (component instanceof Container) {
			for (Component child : ((Container) component).getComponents()) {
				JLabel found = helpChipFor(child, word);
				if (found != null) {
					return found;
				}
			}
		}
		return null;
	}

	private static boolean pixelsEqual(BufferedImage a, BufferedImage b) {
		if (a.getWidth() != b.getWidth() || a.getHeight() != b.getHeight()) {
			return false;
		}
		for (int y = 0; y < a.getHeight(); y++) {
			for (int x = 0; x < a.getWidth(); x++) {
				if (a.getRGB(x, y) != b.getRGB(x, y)) {
					return false;
				}
			}
		}
		return true;
	}

	private static BufferedImage paint(FlipsPanel panel) {
		panel.setSize(PANEL_WIDTH, Math.max(panel.getPreferredSize().height, 400));
		layoutTree(panel);
		panel.setSize(PANEL_WIDTH, Math.max(panel.getPreferredSize().height, 400));
		layoutTree(panel);
		BufferedImage image = new BufferedImage(panel.getWidth(), panel.getHeight(), BufferedImage.TYPE_INT_RGB);
		Graphics2D g2 = image.createGraphics();
		panel.paint(g2);
		g2.dispose();
		return image;
	}

	private static void layoutTree(Component component) {
		component.doLayout();
		if (component instanceof Container) {
			for (Component child : ((Container) component).getComponents()) {
				layoutTree(child);
			}
		}
	}

	private static void write(BufferedImage image, String name) throws Exception {
		File out = new File("build/preview/" + name);
		out.getParentFile().mkdirs();
		ImageIO.write(image, "png", out);
	}

	private static int countDistinctColors(BufferedImage image) {
		java.util.Set<Integer> colors = new java.util.HashSet<>();
		for (int y = 0; y < image.getHeight(); y += 7) {
			for (int x = 0; x < image.getWidth(); x += 7) {
				colors.add(image.getRGB(x, y));
			}
		}
		return colors.size();
	}
}

package app.geuncut.service;

import java.net.HttpURLConnection;
import java.time.Instant;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import app.geuncut.api.ApiFailure;
import app.geuncut.dto.GeOffer;
import app.geuncut.dto.OfferPlacement;
import app.geuncut.service.impl.OfferSyncServiceImpl;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

public class OfferSyncServiceTest {
	private static final Instant T0 = Instant.parse("2026-07-06T03:00:00Z");

	private MockGeUncutApi api;
	private OfferSyncService service;
	private Runnable flushTick;

	@Before
	public void setUp() {
		api = new MockGeUncutApi();
		ScheduledExecutorService executor = mock(ScheduledExecutorService.class);
		service = new OfferSyncServiceImpl(api, executor);
		service.start(() -> "acct-1");

		ArgumentCaptor<Runnable> tick = ArgumentCaptor.forClass(Runnable.class);
		verify(executor).scheduleWithFixedDelay(tick.capture(), anyLong(), anyLong(), any(TimeUnit.class));
		flushTick = tick.getValue();
	}

	@Test
	public void recordedOfferFlushesAsSnapshot() {
		service.record(0, 561, GrandExchangeOfferState.BUYING, 40, 100, 128, T0);
		flushTick.run();

		assertEquals(1, api.postedOffers.size());
		assertEquals(1, api.postedOffers.get(0).size());
		assertEquals("acct-1", api.lastOffersAccountHash);
		GeOffer offer = api.postedOffers.get(0).get(0);
		assertEquals(0, offer.getSlot());
		assertEquals(561, offer.getItemId());
		assertEquals("buy", offer.getSide());
		assertEquals("buying", offer.getState());
		assertEquals(40, offer.getQuantityFilled());
		assertEquals(100, offer.getQuantityTotal());
		assertEquals(128, offer.getPriceEach());
		assertNotNull(api.lastOffersSyncedAt);
	}

	@Test
	public void slotKeepsPlacementTimeAcrossFillsAndReplays() {
		service.record(0, 561, GrandExchangeOfferState.BUYING, 0, 100, 128, T0);
		service.record(0, 561, GrandExchangeOfferState.BUYING, 40, 100, 128, T0.plusSeconds(600));
		flushTick.run();

		assertEquals(T0.toString(), api.postedOffers.get(0).get(0).getOccurredAt());
	}

	@Test
	public void newOfferInSlotGetsFreshPlacementTime() {
		service.record(0, 561, GrandExchangeOfferState.BUYING, 100, 100, 128, T0);
		service.record(0, 561, GrandExchangeOfferState.SELLING, 0, 100, 140, T0.plusSeconds(600));
		flushTick.run();

		assertEquals(T0.plusSeconds(600).toString(), api.postedOffers.get(0).get(0).getOccurredAt());
	}

	@Test
	public void serverSeedAgesOfferAcrossRestart() {
		service.seed(java.util.Collections.singletonList(OfferPlacement.builder()
				.accountHash("acct-1").slot(0).itemId(561).side("buy")
				.priceEach(128).quantityTotal(100).quantityFilled(0)
				.placedAt("2026-07-06T01:30:00").build()));
		service.record(0, 561, GrandExchangeOfferState.BUYING, 40, 100, 128, T0);
		flushTick.run();

		assertEquals("2026-07-06T01:30:00Z", api.postedOffers.get(0).get(0).getOccurredAt());
	}

	@Test
	public void seedIgnoredForADifferentOffer() {
		service.seed(java.util.Collections.singletonList(OfferPlacement.builder()
				.accountHash("acct-1").slot(0).itemId(561).side("buy")
				.priceEach(999).quantityTotal(100).quantityFilled(0)
				.placedAt("2026-07-06T01:30:00").build()));
		service.record(0, 561, GrandExchangeOfferState.BUYING, 0, 100, 128, T0);
		flushTick.run();

		assertEquals(T0.toString(), api.postedOffers.get(0).get(0).getOccurredAt());
	}

	@Test
	public void seedRetroAppliesToAnAlreadyRecordedSlot() {
		service.record(0, 561, GrandExchangeOfferState.BUYING, 40, 100, 128, T0);
		service.seed(java.util.Collections.singletonList(OfferPlacement.builder()
				.accountHash("acct-1").slot(0).itemId(561).side("buy")
				.priceEach(128).quantityTotal(100).quantityFilled(40)
				.placedAt("2026-07-06T01:30:00").build()));
		flushTick.run();

		assertEquals("2026-07-06T01:30:00Z", api.postedOffers.get(0).get(0).getOccurredAt());
	}

	@Test
	public void allOccupiedSlotsFlushTogether() {
		service.record(0, 561, GrandExchangeOfferState.BUYING, 0, 100, 128, T0);
		service.record(1, 556, GrandExchangeOfferState.SELLING, 5, 50, 4, T0);
		flushTick.run();

		assertEquals(1, api.postedOffers.size());
		assertEquals(2, api.postedOffers.get(0).size());
	}

	@Test
	public void emptyStateClearsSlotAndFlushesEmptySnapshot() {
		service.record(0, 561, GrandExchangeOfferState.BUYING, 0, 100, 128, T0);
		flushTick.run();
		service.record(0, 561, GrandExchangeOfferState.EMPTY, 0, 100, 128, T0);
		flushTick.run();

		assertEquals(2, api.postedOffers.size());
		assertTrue(api.postedOffers.get(1).isEmpty());
	}

	@Test
	public void unchangedStateDoesNotReflush() {
		service.record(0, 561, GrandExchangeOfferState.BUYING, 0, 100, 128, T0);
		flushTick.run();
		flushTick.run();

		assertEquals(1, api.postedOffers.size());
	}

	@Test
	public void emptyQueueDoesNotPost() {
		flushTick.run();
		assertTrue(api.postedOffers.isEmpty());
	}

	@Test
	public void failedFlushRetainsStateAndRetries() {
		service.record(0, 561, GrandExchangeOfferState.BUYING, 0, 100, 128, T0);
		api.failNextOffers = true;
		flushTick.run();
		assertTrue(api.postedOffers.isEmpty());

		flushTick.run();
		assertEquals(1, api.postedOffers.size());
		assertEquals(1, api.postedOffers.get(0).size());
	}

	@Test
	public void unauthorizedFlushDropsWithoutRetry() {
		service.record(0, 561, GrandExchangeOfferState.BUYING, 0, 100, 128, T0);
		api.failNextOffers = true;
		api.failure = ApiFailure.http(HttpURLConnection.HTTP_UNAUTHORIZED, "not linked");
		flushTick.run();

		flushTick.run();
		assertTrue(api.postedOffers.isEmpty());
	}

	@Test
	public void sellStateMapsSideAndState() {
		service.record(2, 561, GrandExchangeOfferState.CANCELLED_SELL, 10, 20, 130, T0);
		flushTick.run();

		GeOffer offer = api.postedOffers.get(0).get(0);
		assertEquals("sell", offer.getSide());
		assertEquals("cancelled_sell", offer.getState());
	}

	@Test
	public void malformedOfferIsDropped() {
		service.record(0, 561, GrandExchangeOfferState.BUYING, 0, 0, 128, T0);
		flushTick.run();

		assertTrue(api.postedOffers.isEmpty());
		assertTrue(service.current().isEmpty());
	}

	@Test
	public void currentReturnsWorkingOffers() {
		service.record(0, 561, GrandExchangeOfferState.BUYING, 0, 100, 128, T0);

		assertEquals(1, service.current().size());
		assertEquals(561, service.current().get(0).getItemId());
	}
}

package app.geuncut.service;

import java.util.ArrayList;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.List;

import app.geuncut.api.ApiFailure;
import app.geuncut.dto.LinkSession;
import app.geuncut.service.impl.LinkServiceImpl;
import net.runelite.client.config.ConfigManager;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;

public class LinkServiceTest {
	private MockGeUncutApi api;
	private ConfigManager configManager;
	private ScheduledExecutorService executor;
	private LinkService service;

	private final List<String> shownCodes = new ArrayList<>();
	private final List<ApiFailure> errors = new ArrayList<>();
	private int linkedCalls;

	@Before
	public void setUp() {
		api = new MockGeUncutApi();
		configManager = mock(ConfigManager.class);
		executor = mock(ScheduledExecutorService.class);
		service = new LinkServiceImpl(api, configManager, executor);

		api.session = LinkSession.builder()
				.userCode("ABCD-1234")
				.deviceCode("device-secret")
				.expiresInSeconds(600)
				.build();
	}

	private Runnable begin() {
		service.begin(shownCodes::add, () -> linkedCalls++, errors::add);
		ArgumentCaptor<Runnable> tick = ArgumentCaptor.forClass(Runnable.class);
		verify(executor).scheduleWithFixedDelay(tick.capture(), anyLong(), anyLong(), any(TimeUnit.class));
		return tick.getValue();
	}

	@Test
	public void beginSurfacesTheUserCodeAndStartsPolling() {
		begin();
		assertEquals(1, shownCodes.size());
		assertEquals("ABCD-1234", shownCodes.get(0));
		assertTrue(service.isPairing());
	}

	@Test
	public void pendingPollsKeepTheSessionAlive() {
		Runnable poll = begin();
		poll.run();
		poll.run();

		assertEquals(2, api.pollCount);
		assertEquals(0, linkedCalls);
		assertTrue(service.isPairing());
		verify(configManager, never()).setConfiguration(any(), any(), any(String.class));
	}

	@Test
	public void claimedPollWritesTokenAndFinishes() {
		Runnable poll = begin();
		api.linkToken = "gu_delivered";
		poll.run();

		verify(configManager).setConfiguration("geuncut", "apiToken", "gu_delivered");
		assertEquals(1, linkedCalls);
		assertFalse(service.isPairing());
	}

	@Test
	public void pollErrorCancelsAndReports() {
		Runnable poll = begin();
		api.linkPending = false;
		poll.run();

		assertEquals(1, errors.size());
		assertFalse(service.isPairing());
		verify(configManager, never()).setConfiguration(any(), any(), any(String.class));
	}

	@Test
	public void startFailureReportsWithoutPolling() {
		api.session = null;
		service.begin(shownCodes::add, () -> linkedCalls++, errors::add);

		assertEquals(1, errors.size());
		assertFalse(service.isPairing());
		verify(executor, never()).scheduleWithFixedDelay(any(), anyLong(), anyLong(), any());
	}

	@Test
	public void cancelStopsTheSession() {
		begin();
		service.cancel();
		assertFalse(service.isPairing());
	}

	@Test
	public void staleSessionPollNeverWritesAToken() {
		Runnable stalePoll = begin();
		api.deferNextPoll = true;
		stalePoll.run();

		service.cancel();
		api.session = LinkSession.builder()
				.userCode("WXYZ-9999")
				.deviceCode("device-2")
				.expiresInSeconds(600)
				.build();
		service.begin(shownCodes::add, () -> linkedCalls++, errors::add);

		api.linkToken = "stale-token";
		api.firePendingPoll();

		verify(configManager, never()).setConfiguration(any(), any(), any(String.class));
		assertEquals(0, linkedCalls);
		assertTrue(service.isPairing());
	}
}

