package app.geuncut;

import java.util.List;

import app.geuncut.tracker.OfferAutofill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class OfferRowFitTest {
	private static final int AVAILABLE = 519 - 30;

	private static final long[] PRICES = { 2_512L, 250_000L, 3_210_118L, 116_198_605L, 2_147_483_647L };

	private static List<OfferAutofill.Choice> rendered(long price, int percent) {
		List<OfferAutofill.Choice> all = OfferAutofill.choices(price, OfferAutofill.Prompt.PRICE, percent);
		if (!GeUncutPlugin.fits(all, AVAILABLE)) {
			List<OfferAutofill.Choice> compact =
					OfferAutofill.choices(price, OfferAutofill.Prompt.PRICE, percent, true);
			if (GeUncutPlugin.fits(compact, AVAILABLE)) {
				all = compact;
			}
		}
		return GeUncutPlugin.fitChoices(all, AVAILABLE);
	}

	@Test
	public void allThreePricesRenderAtEveryMagnitude() {
		for (long price : PRICES) {
			for (int percent : new int[] { 1, 2, 5, 10, 50 }) {
				List<OfferAutofill.Choice> shown = rendered(price, percent);
				assertEquals("price " + price + " at " + percent + "% lost a tip", 3, shown.size());
				assertTrue("row overflows at price " + price + " / " + percent + "%",
						GeUncutPlugin.fits(shown, AVAILABLE));
			}
		}
	}

	@Test
	public void theClickedValueIsExactEvenWhenTheLabelIsAbbreviated() {
		List<OfferAutofill.Choice> shown = rendered(2_147_483_647L, 2);
		assertEquals(2_104_533_974L, shown.get(0).getValue());
		assertEquals(2_147_483_647L, shown.get(1).getValue());
		assertEquals(2_190_433_320L, shown.get(2).getValue());
	}

	@Test
	public void smallPricesKeepTheirExactDigits() {
		for (OfferAutofill.Choice choice : rendered(2_512L, 2)) {
			assertTrue("unexpectedly abbreviated: " + choice.getLabel(),
					!choice.getLabel().endsWith("K") && !choice.getLabel().endsWith("M"));
		}
	}

	@Test
	public void aNarrowRowShedsOneTipBeforeFallingBackToOne() {
		List<OfferAutofill.Choice> all =
				OfferAutofill.choices(2_147_483_647L, OfferAutofill.Prompt.PRICE, 50, true);
		assertEquals(3, GeUncutPlugin.fitChoices(all, 400).size());
		assertEquals(2, GeUncutPlugin.fitChoices(all, 250).size());
		assertEquals(1, GeUncutPlugin.fitChoices(all, 100).size());
	}
}

package app.geuncut.tracker;

import java.util.ArrayList;
import java.util.List;

import app.geuncut.dto.GeHistoryRow;
import net.runelite.api.widgets.Widget;

public final class GeHistoryParser {
	private static final int ROW_SCAN_LIMIT = 8;

	private GeHistoryParser() {
	}

	public static List<GeHistoryRow> parse(Widget container) {
		List<GeHistoryRow> rows = new ArrayList<>();
		if (container == null) {
			return rows;
		}
		Widget[] children = container.getDynamicChildren();
		if (children == null) {
			return rows;
		}
		for (int index = 0; index < children.length; index++) {
			String side = side(children[index]);
			if (side == null) {
				continue;
			}
			GeHistoryRow row = parseRow(children, index, side);
			if (row != null) {
				rows.add(row);
			}
		}
		return rows;
	}

	private static String side(Widget widget) {
		String text = plainText(widget);
		if (text == null) {
			return null;
		}
		if (text.startsWith("Bought")) {
			return "buy";
		}
		if (text.startsWith("Sold")) {
			return "sell";
		}
		return null;
	}

	private static GeHistoryRow parseRow(Widget[] children, int headerIndex, String side) {
		int itemId = -1;
		int quantity = 0;
		int priceEach = -1;
		long totalValue = -1;
		int end = Math.min(children.length, headerIndex + 1 + ROW_SCAN_LIMIT);
		for (int index = headerIndex + 1; index < end; index++) {
			Widget child = children[index];
			if (child == null) {
				continue;
			}
			if (side(child) != null) {
				break;
			}
			if (itemId <= 0 && child.getItemId() > 0) {
				itemId = child.getItemId();
				quantity = Math.max(1, child.getItemQuantity());
				continue;
			}
			String text = plainText(child);
			if (text == null) {
				continue;
			}
			if (text.contains("each")) {
				priceEach = parseEach(text);
			} else if (totalValue < 0 && text.contains("coins")) {
				totalValue = digits(truncateAtParen(text));
			}
		}
		if (itemId <= 0 || quantity <= 0) {
			return null;
		}
		if (priceEach <= 0 && totalValue > 0) {
			priceEach = (int) (totalValue / quantity);
		}
		if (priceEach <= 0) {
			return null;
		}
		return GeHistoryRow.builder()
				.itemId(itemId)
				.side(side)
				.quantity(quantity)
				.priceEach(priceEach)
				.build();
	}

	private static int parseEach(String text) {
		int separator = text.lastIndexOf('=');
		if (separator < 0) {
			return -1;
		}
		long value = digits(text.substring(separator + 1));
		return value > 0 && value <= Integer.MAX_VALUE ? (int) value : -1;
	}

	private static String truncateAtParen(String text) {
		int paren = text.indexOf('(');
		return paren < 0 ? text : text.substring(0, paren);
	}

	private static long digits(String text) {
		String cleaned = text.replaceAll("\\D", "");
		if (cleaned.isEmpty() || cleaned.length() > 15) {
			return -1;
		}
		return Long.parseLong(cleaned);
	}

	private static String plainText(Widget widget) {
		String text = widget != null ? widget.getText() : null;
		if (text == null || text.isEmpty()) {
			return null;
		}
		return text.replaceAll("<[^>]*>", " ").trim();
	}
}

package app.geuncut.tracker;

import java.util.ArrayList;
import java.util.List;

import lombok.Value;

public final class OfferAutofill {
	private OfferAutofill() {
	}

	public enum Prompt {
		PRICE, QUANTITY
	}

	@Value
	public static class Choice {
		String label;
		long value;
		boolean base;
	}

	public static Prompt promptKind(String chatboxTitle) {
		if (chatboxTitle == null) {
			return null;
		}
		String title = chatboxTitle.trim();
		if (title.equals("Set a price for each item:")) {
			return Prompt.PRICE;
		}
		if (title.equals("How many do you wish to buy?") || title.equals("How many do you wish to sell?")) {
			return Prompt.QUANTITY;
		}
		return null;
	}

	public static List<Choice> choices(Long resolved, Prompt prompt, int percent) {
		return choices(resolved, prompt, percent, false);
	}

	public static List<Choice> choices(Long resolved, Prompt prompt, int percent, boolean compact) {
		if (resolved == null || resolved <= 0) {
			return List.of();
		}
		long base = resolved;
		if (prompt != Prompt.PRICE || percent <= 0) {
			return List.of(new Choice(format(base, compact), base, true));
		}
		List<Choice> choices = new ArrayList<>(3);
		long low = scale(base, 100 - percent);
		long high = scale(base, 100 + percent);
		choices.add(new Choice("-" + percent + "% " + format(low, compact), low, false));
		choices.add(new Choice(format(base, compact), base, true));
		choices.add(new Choice("+" + percent + "% " + format(high, compact), high, false));
		return choices;
	}

	private static long scale(long base, int percentOfBase) {
		return Math.max(1, Math.round(base * percentOfBase / 100.0));
	}

	private static String format(long value, boolean compact) {
		if (!compact || value < 100_000L) {
			return String.format("%,d", value);
		}
		if (value >= 1_000_000_000L) {
			return trim(value / 1_000_000_000.0) + "B";
		}
		if (value >= 1_000_000L) {
			return trim(value / 1_000_000.0) + "M";
		}
		return trim(value / 1_000.0) + "K";
	}

	private static String trim(double scaled) {
		String text = String.format("%.2f", scaled);
		if (text.endsWith("0")) {
			text = text.substring(0, text.length() - 1);
		}
		if (text.endsWith(".0")) {
			text = text.substring(0, text.length() - 2);
		}
		return text.endsWith("0") && text.contains(".") ? text.substring(0, text.length() - 1) : text;
	}
}

