package app.geuncut.tracker.impl;

import java.time.Instant;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;

import app.geuncut.model.OfferDelta;
import app.geuncut.model.OfferSnapshot;
import app.geuncut.tracker.OfferTracker;
import app.geuncut.tracker.SnapshotStore;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GrandExchangeOfferState;

@Slf4j
@Singleton
public class OfferTrackerImpl implements OfferTracker {
	private final Map<Integer, OfferSnapshot> slots = new HashMap<>();
	private final Set<Integer> replayedSlots = new HashSet<>();
	private final SnapshotStore store;
	private String currentAccount;

	public OfferTrackerImpl() {
		this(new InMemorySnapshotStore());
	}

	@Inject
	public OfferTrackerImpl(SnapshotStore store) {
		this.store = store;
	}

	@Override
	public void onOfferChanged(
			int slot,
			int itemId,
			GrandExchangeOfferState state,
			int quantitySold,
			int spent,
			int totalQuantity,
			int price,
			Instant now,
			Consumer<OfferDelta> onFill) {
		OfferDelta delta = advance(slot, itemId, state, quantitySold, spent, totalQuantity, price, now);
		if (delta != null && onFill != null) {
			onFill.accept(delta);
		}
		persist();
	}

	private OfferDelta advance(
			int slot,
			int itemId,
			GrandExchangeOfferState state,
			int quantitySold,
			int spent,
			int totalQuantity,
			int price,
			Instant now) {
		if (state == GrandExchangeOfferState.EMPTY) {
			return residualFill(slots.remove(slot), slot, now);
		}

		boolean selling = isSellState(state);
		boolean firstSinceReset = replayedSlots.add(slot);
		OfferSnapshot last = slots.get(slot);
		boolean newOffer = last == null
				|| last.getItemId() != itemId
				|| isSellState(last.getState()) != selling
				|| quantitySold < last.getQuantitySold()
				|| last.getOfferId() == null;
		String offerId = newOffer ? UUID.randomUUID().toString() : last.getOfferId();
		slots.put(slot, new OfferSnapshot(itemId, quantitySold, spent, state, totalQuantity, price, offerId));

		if (last == null || last.getItemId() != itemId || isSellState(last.getState()) != selling) {
			if (quantitySold > 0 && firstSinceReset) {
				return null;
			}
			last = new OfferSnapshot(itemId, 0, 0, state, totalQuantity, price, offerId);
		}

		int quantityDelta = quantitySold - last.getQuantitySold();
		int spentDelta = spent - last.getSpent();
		if (quantityDelta <= 0 || spentDelta <= 0) {
			if (quantityDelta > 0 && spentDelta < 0) {
				log.warn("event=fill_discarded_negative_spend item={} slot={} quantity_delta={} spent_delta={}",
						itemId, slot, quantityDelta, spentDelta);
			}
			return null;
		}

		int priceEach = (int) Math.round((double) spentDelta / quantityDelta);
		OfferDelta.Side side = selling ? OfferDelta.Side.SELL : OfferDelta.Side.BUY;
		return new OfferDelta(itemId, side, quantityDelta, priceEach, slot, now, offerId, quantitySold);
	}

	private OfferDelta residualFill(OfferSnapshot last, int slot, Instant now) {
		if (last == null || !isActiveState(last.getState())) {
			return null;
		}
		int missing = last.getQuantityTotal() - last.getQuantitySold();
		if (missing <= 0 || last.getPrice() <= 0) {
			return null;
		}
		OfferDelta.Side side = isSellState(last.getState()) ? OfferDelta.Side.SELL : OfferDelta.Side.BUY;
		String offerId = last.getOfferId() != null ? last.getOfferId() : UUID.randomUUID().toString();
		log.debug("event=residual_fill_on_empty item={} slot={} missing={} price={}",
				last.getItemId(), slot, missing, last.getPrice());
		return new OfferDelta(last.getItemId(), side, missing, last.getPrice(), slot, now,
				offerId, last.getQuantityTotal());
	}

	@Override
	public void loadFor(String accountHash) {
		currentAccount = accountHash;
		slots.clear();
		if (accountHash != null) {
			slots.putAll(store.load(accountHash));
		}
	}

	@Override
	public void reset() {
		slots.clear();
		replayedSlots.clear();
	}

	private void persist() {
		if (currentAccount != null) {
			store.save(currentAccount, slots);
		}
	}

	private static boolean isActiveState(GrandExchangeOfferState state) {
		return state == GrandExchangeOfferState.BUYING
				|| state == GrandExchangeOfferState.SELLING;
	}

	private static boolean isSellState(GrandExchangeOfferState state) {
		return state == GrandExchangeOfferState.SELLING
				|| state == GrandExchangeOfferState.SOLD
				|| state == GrandExchangeOfferState.CANCELLED_SELL;
	}
}

package app.geuncut.tracker.impl;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import javax.inject.Singleton;

import app.geuncut.model.Purchase;
import app.geuncut.tracker.BuyLimitTracker;

@Singleton
public class BuyLimitTrackerImpl implements BuyLimitTracker {
	private static final Duration WINDOW = Duration.ofHours(4);

	private final Map<Integer, Deque<Purchase>> purchasesByItem = new HashMap<>();

	@Override
	public void recordBuy(int itemId, int quantity, Instant boughtAt) {
		purchasesByItem.computeIfAbsent(itemId, unseenItemId -> new ArrayDeque<>()).addLast(new Purchase(quantity, boughtAt));
	}

	@Override
	public int boughtInWindow(int itemId, Instant now) {
		Deque<Purchase> purchases = purchasesByItem.get(itemId);
		if (purchases == null) {
			return 0;
		}
		Instant cutoff = now.minus(WINDOW);
		purchases.removeIf(purchase -> purchase.getBoughtAt().isBefore(cutoff));
		if (purchases.isEmpty()) {
			purchasesByItem.remove(itemId);
			return 0;
		}
		return purchases.stream().mapToInt(Purchase::getQuantity).sum();
	}

	@Override
	public Optional<Instant> nextReset(int itemId, Instant now) {
		Deque<Purchase> purchases = purchasesByItem.get(itemId);
		if (purchases == null || boughtInWindow(itemId, now) == 0) {
			return Optional.empty();
		}
		return Optional.of(purchases.peekFirst().getBoughtAt().plus(WINDOW));
	}

	@Override
	public void reset() {
		purchasesByItem.clear();
	}
}

package app.geuncut.tracker.impl;

import java.io.BufferedInputStream;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.RandomAccessFile;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import app.geuncut.dto.GeTradeEvent;
import app.geuncut.tracker.FillBatch;
import app.geuncut.tracker.FillLog;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class FileFillLog implements FillLog {
	private final Gson gson;
	private final File dir;
	private final Object lock = new Object();
	private final Set<String> prepared = new HashSet<>();
	private final Map<String, Long> entryCounts = new HashMap<>();

	public FileFillLog(Gson gson, File dir) {
		this.gson = gson;
		this.dir = dir;
	}

	private File fileFor(String accountHash) {
		return new File(dir, "fills-" + accountHash + ".jsonl");
	}

	private File cursorFor(String accountHash) {
		return new File(dir, "fills-" + accountHash + ".sent");
	}

	@Override
	public void append(String accountHash, GeTradeEvent event) {
		if (accountHash == null || event == null || event.getIdempotencyKey() == null) {
			return;
		}
		synchronized (lock) {
			prepare(accountHash);
			File file = fileFor(accountHash);
			File parent = file.getParentFile();
			if (parent != null) {
				parent.mkdirs();
			}
			long seq = entryCount(accountHash);
			GeTradeEvent numbered = event.toBuilder().seq(seq).build();
			try {
				Files.write(file.toPath(), (gson.toJson(numbered) + "\n").getBytes(StandardCharsets.UTF_8),
						StandardOpenOption.CREATE, StandardOpenOption.APPEND);
				entryCounts.put(accountHash, seq + 1);
			} catch (IOException e) {
				log.warn("event=fill_log_append_failed account={} error={}", accountHash, e.getMessage());
			}
		}
	}

	@Override
	public FillBatch read(String accountHash, long offset, int maxEntries) {
		List<GeTradeEvent> entries = new ArrayList<>();
		if (accountHash == null || maxEntries <= 0) {
			return new FillBatch(entries, Math.max(0, offset));
		}
		synchronized (lock) {
			prepare(accountHash);
			File file = fileFor(accountHash);
			long start = Math.max(0, offset);
			if (!file.isFile() || start >= file.length()) {
				return new FillBatch(entries, start);
			}
			long position = start;
			try (InputStream raw = new FileInputStream(file);
					BufferedInputStream in = new BufferedInputStream(raw)) {
				skipFully(in, start);
				ByteArrayOutputStream line = new ByteArrayOutputStream();
				int read;
				while (entries.size() < maxEntries && (read = in.read()) >= 0) {
					line.write(read);
					if (read != '\n') {
						continue;
					}
					position += line.size();
					GeTradeEvent event = parse(accountHash, line.toString("UTF-8"));
					line.reset();
					if (event != null) {
						entries.add(event);
					}
				}
			} catch (IOException e) {
				log.warn("event=fill_log_read_failed account={} error={}", accountHash, e.getMessage());
			}
			return new FillBatch(entries, position);
		}
	}

	@Override
	public long deliveredOffset(String accountHash) {
		if (accountHash == null) {
			return 0;
		}
		synchronized (lock) {
			File cursor = cursorFor(accountHash);
			if (!cursor.isFile()) {
				return 0;
			}
			try {
				String raw = new String(Files.readAllBytes(cursor.toPath()), StandardCharsets.UTF_8).trim();
				long offset = Long.parseLong(raw);
				long size = fileFor(accountHash).length();
				return offset < 0 ? 0 : Math.min(offset, size);
			} catch (IOException | NumberFormatException unusable) {
				log.warn("event=fill_log_cursor_unreadable account={}", accountHash);
				return 0;
			}
		}
	}

	@Override
	public void markDelivered(String accountHash, long offset) {
		if (accountHash == null) {
			return;
		}
		synchronized (lock) {
			if (offset <= deliveredOffset(accountHash)) {
				return;
			}
			File cursor = cursorFor(accountHash);
			File parent = cursor.getParentFile();
			if (parent != null) {
				parent.mkdirs();
			}
			Path target = cursor.toPath();
			Path tmp = new File(parent, cursor.getName() + ".tmp").toPath();
			try {
				Files.write(tmp, Long.toString(offset).getBytes(StandardCharsets.UTF_8));
				try {
					Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
				} catch (IOException atomicUnsupported) {
					Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING);
				}
			} catch (IOException e) {
				log.warn("event=fill_log_cursor_write_failed account={} error={}", accountHash, e.getMessage());
				try {
					Files.deleteIfExists(tmp);
				} catch (IOException ignored) {
				}
			}
		}
	}

	private GeTradeEvent parse(String accountHash, String line) {
		String trimmed = line.trim();
		if (trimmed.isEmpty()) {
			return null;
		}
		try {
			GeTradeEvent event = gson.fromJson(trimmed, GeTradeEvent.class);
			return event != null && event.getIdempotencyKey() != null ? event : null;
		} catch (RuntimeException malformed) {
			log.warn("event=fill_log_bad_line account={}", accountHash);
			return null;
		}
	}

	private long entryCount(String accountHash) {
		Long known = entryCounts.get(accountHash);
		if (known != null) {
			return known;
		}
		long counted = 0;
		File file = fileFor(accountHash);
		if (file.isFile()) {
			try (InputStream raw = new FileInputStream(file);
					BufferedInputStream in = new BufferedInputStream(raw)) {
				int read;
				while ((read = in.read()) >= 0) {
					if (read == '\n') {
						counted++;
					}
				}
			} catch (IOException e) {
				log.warn("event=fill_log_count_failed account={} error={}", accountHash, e.getMessage());
			}
		}
		entryCounts.put(accountHash, counted);
		return counted;
	}

	private void prepare(String accountHash) {
		if (!prepared.add(accountHash)) {
			return;
		}
		File file = fileFor(accountHash);
		if (!file.isFile() || file.length() == 0) {
			return;
		}
		try (RandomAccessFile handle = new RandomAccessFile(file, "r")) {
			handle.seek(file.length() - 1);
			if (handle.read() == '\n') {
				return;
			}
		} catch (IOException e) {
			log.warn("event=fill_log_tail_unreadable account={} error={}", accountHash, e.getMessage());
			return;
		}
		try {
			Files.write(file.toPath(), "\n".getBytes(StandardCharsets.UTF_8), StandardOpenOption.APPEND);
			log.warn("event=fill_log_torn_line_sealed account={}", accountHash);
		} catch (IOException e) {
			log.warn("event=fill_log_seal_failed account={} error={}", accountHash, e.getMessage());
		}
	}

	private static void skipFully(InputStream in, long count) throws IOException {
		long remaining = count;
		while (remaining > 0) {
			long skipped = in.skip(remaining);
			if (skipped <= 0) {
				if (in.read() < 0) {
					return;
				}
				skipped = 1;
			}
			remaining -= skipped;
		}
	}
}

package app.geuncut.tracker.impl;

import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

import app.geuncut.config.GeUncutConfig;
import app.geuncut.model.OfferSnapshot;
import app.geuncut.tracker.SnapshotStore;
