import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;

import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

public class ItemIconLoader {
	private static final int MAX_CACHE = 512;

	private final OkHttpClient http;
	private final ItemManager itemManager;
	private final Map<String, ImageIcon> cache = Collections.synchronizedMap(
			new LinkedHashMap<String, ImageIcon>(64, 0.75f, true) {
				@Override
				protected boolean removeEldestEntry(Map.Entry<String, ImageIcon> eldest) {
					return size() > MAX_CACHE;
				}
			});

	public ItemIconLoader(OkHttpClient http, ItemManager itemManager) {
		this.http = http;
		this.itemManager = itemManager;
	}

	Image sprite(int itemId, Runnable onLoaded) {
		AsyncBufferedImage image = itemManager.getImage(itemId);
		image.onLoaded(() -> SwingUtilities.invokeLater(onLoaded));
		return image;
	}

	void load(int itemId, String name, JLabel label, int size) {
		AsyncBufferedImage sprite = itemManager.getImage(itemId);
		sprite.onLoaded(() -> SwingUtilities.invokeLater(() ->
				label.setIcon(new ImageIcon(fit(sprite, size)))));
		label.setIcon(new ImageIcon(fit(sprite, size)));
		if (name == null || name.trim().isEmpty()) {
			return;
		}
		String key = itemId + ":" + size;
		ImageIcon cached = cache.get(key);
		if (cached != null) {
			label.setIcon(cached);
			return;
		}
		http.newCall(new Request.Builder().url(detailUrl(name)).build()).enqueue(new Callback() {
			@Override
			public void onFailure(Call call, IOException exception) {
			}

			@Override
			public void onResponse(Call call, Response response) {
				try (Response managed = response) {
					if (!managed.isSuccessful() || managed.body() == null) {
						return;
					}
					BufferedImage image = ImageIO.read(managed.body().byteStream());
					if (image == null) {
						return;
					}
					ImageIcon icon = new ImageIcon(fit(image, size));
					cache.put(key, icon);
					SwingUtilities.invokeLater(() -> label.setIcon(icon));
				} catch (IOException unreadable) {
				}
			}
		});
	}

	private static Image fit(BufferedImage image, int size) {
		int width = image.getWidth();
		int height = image.getHeight();
		double scale = (double) size / Math.max(width, height);
		int scaledWidth = Math.max(1, (int) Math.round(width * scale));
		int scaledHeight = Math.max(1, (int) Math.round(height * scale));
		return image.getScaledInstance(scaledWidth, scaledHeight, Image.SCALE_SMOOTH);
	}

	private static String detailUrl(String name) {
		String file = name.trim().replace(' ', '_') + "_detail.png";
		return "https://oldschool.runescape.wiki/images/thumb/" + file + "/96px-" + file;
	}
}

package app.geuncut.ui;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Component;
import java.awt.Composite;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntConsumer;
import javax.swing.JComponent;
import javax.swing.Timer;

import app.geuncut.dto.MoverEntry;

class MoversRotator extends JComponent {
	private static final int PAGE = 5;
	private static final int DWELL_MS = 10_000;
	private static final int FADE_MS = 650;
	private static final int TICK_MS = 16;
	private static final int ROW_HEIGHT = 36;
	private static final int ICON = 20;
	private static final int TEXT_X = ICON + 8;
	private static final int NAME_GAP = 8;

	interface IconProvider {
		Image icon(int itemId, Runnable onLoaded);
	}

	private final Font numberFont;
	private final Color pctColor;
	private final IconProvider icons;
	private final IntConsumer onOpen;
	private final java.util.function.Function<MoverEntry, String> valueText;
	private final List<Row> rows = new ArrayList<>();
	private final Timer timer;

	private int page;
	private int fadingFrom = -1;
	private long fadeStartNanos;
	private long pageShownNanos;

	MoversRotator(Font numberFont, Color pctColor, IconProvider icons, IntConsumer onOpen) {
		this(numberFont, pctColor, icons, onOpen,
				entry -> String.format("%+.1f%%", entry.getChangePct()));
	}

	MoversRotator(Font numberFont, Color pctColor, IconProvider icons, IntConsumer onOpen,
			java.util.function.Function<MoverEntry, String> valueText) {
		this.numberFont = numberFont;
		this.pctColor = pctColor;
		this.icons = icons;
		this.onOpen = onOpen;
		this.valueText = valueText;
		setOpaque(true);
		setBackground(Theme.SURFACE);
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		addMouseListener(new MouseAdapter() {
			@Override
			public void mouseClicked(MouseEvent event) {
				int index = page * PAGE + event.getY() / ROW_HEIGHT;
				if (onOpen != null && index >= 0 && index < rows.size()) {
					onOpen.accept(rows.get(index).itemId);
				}
			}
		});
		timer = new Timer(TICK_MS, event -> tick());
	}

	void setEntries(List<MoverEntry> next) {
		rows.clear();
		if (next != null) {
			for (MoverEntry entry : next) {
				if (entry == null || entry.getName() == null) {
					continue;
				}
				Row row = new Row(entry.getName(), valueText.apply(entry),
						detailLine(entry), entry.getItemId());
				row.icon = icons.icon(entry.getItemId(), this::repaint);
				rows.add(row);
			}
		}
		page = 0;
		fadingFrom = -1;
		pageShownNanos = nowNanos();
		int visibleRows = totalPages() > 1 ? PAGE : rows.size();
		Dimension size = new Dimension(10, visibleRows * ROW_HEIGHT);
		setPreferredSize(size);
		setMaximumSize(new Dimension(Integer.MAX_VALUE, visibleRows * ROW_HEIGHT));
		if (totalPages() > 1) {
			if (!timer.isRunning()) {
				timer.start();
			}
		} else {
			timer.stop();
		}
		revalidate();
		repaint();
	}

	private int totalPages() {
		return rows.isEmpty() ? 0 : (rows.size() + PAGE - 1) / PAGE;
	}

	private static String detailLine(MoverEntry entry) {
		if (entry.getPrice() == null) {
			return null;
		}
		String line = String.format("%,d gp", entry.getPrice());
		if (entry.getVolumeDay() != null && entry.getVolumeDay() > 0) {
			line += " · " + shortAmount(entry.getVolumeDay()) + " vol";
		}
		return line;
	}

	private static String shortAmount(long value) {
		if (value >= 1_000_000) {
			return String.format("%.1fM", value / 1_000_000.0);
		}
		if (value >= 1_000) {
			return Math.round(value / 1000.0) + "k";
		}
		return Long.toString(value);
	}

	void tick() {
		long now = nowNanos();
		if (fadingFrom >= 0) {
			if (now - fadeStartNanos >= FADE_MS * 1_000_000L) {
				fadingFrom = -1;
				pageShownNanos = now;
			}
			repaint();
		} else if (totalPages() > 1 && now - pageShownNanos >= DWELL_MS * 1_000_000L) {
			fadingFrom = page;
			page = (page + 1) % totalPages();
			fadeStartNanos = now;
			repaint();
		}
	}

	long nowNanos() {
		return System.nanoTime();
	}

	@Override
	public void addNotify() {
		super.addNotify();
		if (totalPages() > 1 && !timer.isRunning()) {
			fadingFrom = -1;
			pageShownNanos = nowNanos();
			timer.start();
		}
	}

	@Override
	public void removeNotify() {
		timer.stop();
		super.removeNotify();
	}

	@Override
	protected void paintComponent(Graphics g) {
		super.paintComponent(g);
		g.setColor(getBackground());
		g.fillRect(0, 0, getWidth(), getHeight());
		if (rows.isEmpty()) {
			return;
		}
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		if (fadingFrom >= 0) {
			double progress = (nowNanos() - fadeStartNanos) / (FADE_MS * 1_000_000.0);
			progress = Math.max(0.0, Math.min(1.0, progress));
			if (progress < 0.5) {
				paintPage(g2, fadingFrom, (float) (1.0 - progress * 2.0));
			} else {
				paintPage(g2, page, (float) (progress * 2.0 - 1.0));
			}
		} else {
			paintPage(g2, page, 1f);
		}
		g2.dispose();
	}

	private void paintPage(Graphics2D g2, int pageIndex, float alpha) {
		if (alpha <= 0f) {
			return;
		}
		Composite base = g2.getComposite();
		g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.min(1f, alpha)));
		FontMetrics nameMetrics = g2.getFontMetrics(Theme.BODY);
		FontMetrics pctMetrics = g2.getFontMetrics(numberFont);
		FontMetrics detailMetrics = g2.getFontMetrics(Theme.NUM_SMALL);
		int start = pageIndex * PAGE;
		int end = Math.min(start + PAGE, rows.size());
		for (int index = start; index < end; index++) {
			Row row = rows.get(index);
			int rowY = (index - start) * ROW_HEIGHT;
			int line1 = rowY + 14;
			int line2 = rowY + 29;
			if (row.icon != null) {
				g2.drawImage(row.icon, 0, rowY + (ROW_HEIGHT - ICON) / 2, ICON, ICON, null);
			}
			g2.setFont(Theme.BODY);
			int arrowX = getWidth() - nameMetrics.stringWidth("↗");
			g2.setColor(Theme.MUTED);
			g2.drawString("↗", arrowX, line1);
			g2.setColor(Theme.INK);
			g2.drawString(truncate(row.name, nameMetrics, arrowX - NAME_GAP - TEXT_X), TEXT_X, line1);
			g2.setFont(numberFont);
			g2.setColor(pctColor);
			int pctX = getWidth() - pctMetrics.stringWidth(row.pct);
			g2.drawString(row.pct, pctX, line2);
			if (row.detail != null) {
				g2.setFont(Theme.NUM_SMALL);
				g2.setColor(Theme.INK);
				g2.drawString(truncate(row.detail, detailMetrics, pctX - NAME_GAP - TEXT_X), TEXT_X, line2);
			}
		}
		g2.setComposite(base);
	}

	private static String truncate(String text, FontMetrics metrics, int maxWidth) {
		if (maxWidth <= 0 || metrics.stringWidth(text) <= maxWidth) {
			return text;
		}
		int ellipsisWidth = metrics.stringWidth("…");
		int end = text.length();
		while (end > 0 && metrics.stringWidth(text.substring(0, end)) + ellipsisWidth > maxWidth) {
			end--;
		}
		return text.substring(0, Math.max(0, end)) + "…";
	}

	static final class Row {
		private final String name;
		private final String pct;
		private final String detail;
		private final int itemId;
		private Image icon;

		Row(String name, String pct, String detail, int itemId) {
			this.name = name;
			this.pct = pct;
			this.detail = detail;
			this.itemId = itemId;
		}
	}
}

package app.geuncut.ui;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JPanel;

class RoundedPanel extends JPanel {
	private final int arc;
	private Color fill;
	private final Color border;

	RoundedPanel(int arc, Color fill, Color border) {
		this.arc = arc;
		this.fill = fill;
		this.border = border;
		setOpaque(false);
	}

	void setFill(Color fill) {
		this.fill = fill;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g) {
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth();
		int h = getHeight();
		if (fill != null) {
			g2.setColor(fill);
			g2.fillRoundRect(0, 0, w - 1, h - 1, arc, arc);
		}
		if (border != null) {
			g2.setColor(border);
			g2.drawRoundRect(0, 0, w - 1, h - 1, arc, arc);
		}
		g2.dispose();
		super.paintComponent(g);
	}
}

