		return values[selectedIndex];
	}

	void setOptions(String[] labels, String[] values, String desiredValue) {
		this.labels = labels;
		this.values = values;
		selectedIndex = 0;
		for (int i = 0; i < values.length; i++) {
			if (values[i].equals(desiredValue)) {
				selectedIndex = i;
				break;
			}
		}
		valueLabel.setText(labels[selectedIndex]);
	}

	private void toggleMenu() {
		if (shouldOpen(System.currentTimeMillis())) {
			showMenu();
		}
	}

	boolean shouldOpen(long now) {
		if (hiddenAt >= 0 && now - hiddenAt <= SAME_CLICK_MS) {
			hiddenAt = -1;
			return false;
		}
		return true;
	}

	void markHidden(long at) {
		hiddenAt = at;
	}

	private void showMenu() {
		JPopupMenu menu = new JPopupMenu();
		this.menu = menu;
		menu.setBackground(Theme.RAISED);
		menu.setBorder(BorderFactory.createLineBorder(Theme.LINE_STRONG));
		menu.addPopupMenuListener(new PopupMenuListener() {
			@Override
			public void popupMenuWillBecomeVisible(PopupMenuEvent event) {
			}

			@Override
			public void popupMenuWillBecomeInvisible(PopupMenuEvent event) {
				markHidden(System.currentTimeMillis());
			}

			@Override
			public void popupMenuCanceled(PopupMenuEvent event) {
			}
		});
		for (int i = 0; i < labels.length; i++) {
			JMenuItem item = new JMenuItem(labels[i]);
			item.setBackground(Theme.RAISED);
			item.setForeground(i == selectedIndex ? Theme.WHITE : Theme.INK);
			item.setFont(Theme.BODY);
			item.setBorder(BorderFactory.createEmptyBorder(4, 9, 4, 9));
			int index = i;
			item.addActionListener(event -> select(index));
			menu.add(item);
		}
		menu.show(this, 0, getHeight() + 2);
	}

	boolean menuShowing() {
		return menu != null && menu.isVisible();
	}

	JPopupMenu getMenuForTest() {
		return menu;
	}

	void selectLabelForTest(String label) {
		for (int i = 0; i < labels.length; i++) {
			if (labels[i].equals(label)) {
				selectedIndex = i;
				valueLabel.setText(labels[i]);
				return;
			}
		}
		throw new IllegalArgumentException("no such option: " + label);
	}

	private void select(int index) {
		if (index == selectedIndex) {
			return;
		}
		selectedIndex = index;
		valueLabel.setText(labels[index]);
		onChange.run();
	}
}

package app.geuncut.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.Icon;

class TradeGlyph implements Icon {
	private final boolean flipped;
	private final Color color;
	private final int size;

	TradeGlyph(boolean flipped, Color color, int size) {
		this.flipped = flipped;
		this.color = color;
		this.size = size;
	}

	@Override
	public void paintIcon(Component component, Graphics g, int x, int y) {
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(color);
		float unit = size / 24f;
		g2.setStroke(new BasicStroke(2.4f * unit, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g2.translate(x, y);
		if (flipped) {
			drawArrow(g2, unit, 3, 21, 8, true);
			drawArrow(g2, unit, 21, 3, 16, false);
		} else {
			drawArrow(g2, unit, 4, 20, 12, true);
		}
		g2.dispose();
	}

	private static void drawArrow(Graphics2D g2, float unit, int fromX, int toX, int yUnits, boolean right) {
		int y = Math.round(yUnits * unit);
		g2.drawLine(Math.round(fromX * unit), y, Math.round(toX * unit), y);
		int head = Math.round(4 * unit);
		int tipX = Math.round(toX * unit);
		int backX = right ? tipX - head : tipX + head;
		g2.drawLine(backX, y - head, tipX, y);
		g2.drawLine(backX, y + head, tipX, y);
	}

	@Override
	public int getIconWidth() {
		return size;
	}

	@Override
	public int getIconHeight() {
		return size;
	}
}

